import * as Slot from "@radix-ui/react-slot"
import type * as React from "react"
import { cn } from "@/lib/utils"

/**
 * A text segment inside a button group: the chip's field name, operator and
 * value. It lives with the filter bar, not the button group, because most
 * design systems' button groups ship no text part.
 */
export function ButtonGroupText({
  className,
  asChild = false,
  ...props
}: React.ComponentProps<"div"> & { asChild?: boolean }) {
  const Comp = asChild ? Slot.Root : "div"
  return (
    <Comp
      data-slot="button-group-text"
      className={cn(
        "border-input bg-muted flex items-center gap-2 rounded-md border px-3 text-sm font-medium *:[svg]:pointer-events-none *:[svg]:size-4 *:[svg]:shrink-0",
        className
      )}
      {...props}
    />
  )
}

