  "data-drop-edge:after:absolute",
  "data-drop-edge:after:start-0 data-drop-edge:after:end-1",
  "data-drop-edge:after:h-0.5 data-drop-edge:after:rounded-full",
  "data-drop-edge:after:bg-primary",
